function New-TestPng([string]$Path,[int]$Width,[int]$Height){$stride=$Width*4;$pixels=New-Object byte[] ($stride*$Height);for($i=0;$i-lt$pixels.Length;$i+=4){$pixels[$i]=20;$pixels[$i+1]=40;$pixels[$i+2]=60;$pixels[$i+3]=255};$bitmap=[Windows.Media.Imaging.BitmapSource]::Create($Width,$Height,96,96,[Windows.Media.PixelFormats]::Bgra32,$null,$pixels,$stride);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($bitmap));$stream=[IO.File]::Open($Path,[IO.FileMode]::Create,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$encoder.Save($stream)}finally{$stream.Dispose()}}
